UPDATE tools SET long_description = E'Ideogram, c''est génération d''images IA avec texte intégré — le meilleur du marché pour la typo. À partir de 6.93€/mois. Particulièrement pertinent pour les graphiste-da et les community-manager.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : visuels avec texte intégré (affiches, covers, thumbnails). À éviter si : midjourney pour usage purement artistique sans texte. Complémentaire à Midjourney — couvre un angle différent.', long_description_en = E'Ideogram is aI image generation with integrated text — the market leader for typography. Starting at €6.93/month. Most relevant for graphiste-da and community-manager.\n\nEstimated time saving: 4h/month with regular use.' WHERE slug = 'ideogram';
